function field({ type, defaultValue, min, max, enum: values, unit, scopes, applyMode, sensitive = false, required = true, owner, consumers, classification = 'admin_runtime_config', descriptionTh, descriptionEn }) {
  return Object.freeze({
    type,
    default: defaultValue,
    min,
    max,
    enum: values,
    unit,
    scopes: Object.freeze(scopes),
    applyMode,
    sensitive,
    required,
    owner,
    consumers: Object.freeze(consumers),
    classification,
    description: Object.freeze({ th: descriptionTh, en: descriptionEn }),
  });
}

